import{_ as a,o,c as r,a2 as t}from"./chunks/framework.BWuWLRhz.js";const b=JSON.parse('{"title":"Class: Fixed","description":"","frontmatter":{},"headers":[],"relativePath":"api/helix/classes/Fixed.md","filePath":"api/helix/classes/Fixed.md"}'),c={name:"api/helix/classes/Fixed.md"};function d(n,e,i,s,h,l){return o(),r("div",null,[...e[0]||(e[0]=[t('<p><a href="./../">helix</a> / Fixed</p><h1 id="class-fixed" tabindex="-1">Class: Fixed <a class="header-anchor" href="#class-fixed" aria-label="Permalink to &quot;Class: Fixed&quot;">​</a></h1><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/helix/src/core/frontend/nodes/fixed.ts#L24" target="_blank" rel="noreferrer">core/frontend/nodes/fixed.ts:24</a></p><p>A <strong>fixed-point scalar</strong>: one integer <a href="./Score.html">Score</a> that stands for a fractional value, encoded as <code>realValue × scale</code>. Minecraft scoreboards are integer-only, so fractions are carried by a fixed <code>scale</code> factor - and every multiply/divide has to rebalance it. Multiply two scaled values and the scale squares; divide and the fraction is floored away. <code>Fixed</code> makes that bookkeeping part of the type and the method names instead of a comment you have to keep in your head.</p><p><strong>Why a scale <code>Score</code> and not just a number.</strong> A <code>scoreboard players operation</code> operand must itself be a score - you can&#39;t <code>*= 1000</code> against a literal. So a <code>Fixed</code> that wants to multiply or divide by its own scale carries <code>scaleScore</code>, a slot seeded once at load to <code>scale</code> (e.g. <code>ctx.scoreSet(scaleScore.set(1000))</code>). The plain <code>number</code> <code>scale</code> is kept alongside for reasoning and asserts. Ops that don&#39;t touch the scale (<code>assign</code>/<code>add</code>/<code>sub</code>/<code>negate</code>/<code>gain</code>/<code>reduce</code>/<code>clamp</code>) need no <code>scaleScore</code>; <a href="#mul">mul</a> and <a href="#divide">divide</a> do.</p><p>Like <a href="./Score.html">Score</a>/<a href="./ScoreVec3.html">ScoreVec3</a> it holds a <em>reference</em> to an existing slot and allocates nothing, emits into the <strong>ambient</strong> context (pass <code>ctx</code> to override), and chains by returning <code>this</code>. Division floors toward −∞ (integer scoreboard divide).</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to &quot;Constructors&quot;">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to &quot;Constructor&quot;">​</a></h3><blockquote><p><strong>new Fixed</strong>(<code>score</code>, <code>scale</code>, <code>scaleScore?</code>): <code>Fixed</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/helix/src/core/frontend/nodes/fixed.ts#L25" target="_blank" rel="noreferrer">core/frontend/nodes/fixed.ts:25</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="score" tabindex="-1">score <a class="header-anchor" href="#score" aria-label="Permalink to &quot;score&quot;">​</a></h5><p><a href="./Score.html"><code>Score</code></a></p><h5 id="scale" tabindex="-1">scale <a class="header-anchor" href="#scale" aria-label="Permalink to &quot;scale&quot;">​</a></h5><p><code>number</code></p><h5 id="scalescore" tabindex="-1">scaleScore? <a class="header-anchor" href="#scalescore" aria-label="Permalink to &quot;scaleScore?&quot;">​</a></h5><p><a href="./Score.html"><code>Score</code></a></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Fixed</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="scale-1" tabindex="-1">scale <a class="header-anchor" href="#scale-1" aria-label="Permalink to &quot;scale&quot;">​</a></h3><blockquote><p><code>readonly</code> <strong>scale</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/helix/src/core/frontend/nodes/fixed.ts#L27" target="_blank" rel="noreferrer">core/frontend/nodes/fixed.ts:27</a></p><hr><h3 id="scalescore-1" tabindex="-1">scaleScore? <a class="header-anchor" href="#scalescore-1" aria-label="Permalink to &quot;scaleScore?&quot;">​</a></h3><blockquote><p><code>readonly</code> <code>optional</code> <strong>scaleScore?</strong>: <a href="./Score.html"><code>Score</code></a></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/helix/src/core/frontend/nodes/fixed.ts#L28" target="_blank" rel="noreferrer">core/frontend/nodes/fixed.ts:28</a></p><hr><h3 id="score-1" tabindex="-1">score <a class="header-anchor" href="#score-1" aria-label="Permalink to &quot;score&quot;">​</a></h3><blockquote><p><code>readonly</code> <strong>score</strong>: <a href="./Score.html"><code>Score</code></a></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/helix/src/core/frontend/nodes/fixed.ts#L26" target="_blank" rel="noreferrer">core/frontend/nodes/fixed.ts:26</a></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="add" tabindex="-1">add() <a class="header-anchor" href="#add" aria-label="Permalink to &quot;add()&quot;">​</a></h3><blockquote><p><strong>add</strong>(<code>other</code>, <code>ctx?</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/helix/src/core/frontend/nodes/fixed.ts#L50" target="_blank" rel="noreferrer">core/frontend/nodes/fixed.ts:50</a></p><p><code>this += other</code> - same-scale addition is just integer <code>+=</code>.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="other" tabindex="-1">other <a class="header-anchor" href="#other" aria-label="Permalink to &quot;other&quot;">​</a></h5><p><a href="./Score.html"><code>Score</code></a> | <code>Fixed</code></p><h5 id="ctx" tabindex="-1">ctx? <a class="header-anchor" href="#ctx" aria-label="Permalink to &quot;ctx?&quot;">​</a></h5><p><a href="./FunctionContext.html"><code>FunctionContext</code></a></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="assign" tabindex="-1">assign() <a class="header-anchor" href="#assign" aria-label="Permalink to &quot;assign()&quot;">​</a></h3><blockquote><p><strong>assign</strong>(<code>other</code>, <code>ctx?</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/helix/src/core/frontend/nodes/fixed.ts#L44" target="_blank" rel="noreferrer">core/frontend/nodes/fixed.ts:44</a></p><p><code>this = other</code> (same scale; <code>other</code> may be a raw <code>Score</code> already at this scale).</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="other-1" tabindex="-1">other <a class="header-anchor" href="#other-1" aria-label="Permalink to &quot;other&quot;">​</a></h5><p><a href="./Score.html"><code>Score</code></a> | <code>Fixed</code></p><h5 id="ctx-1" tabindex="-1">ctx? <a class="header-anchor" href="#ctx-1" aria-label="Permalink to &quot;ctx?&quot;">​</a></h5><p><a href="./FunctionContext.html"><code>FunctionContext</code></a></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="clamp" tabindex="-1">clamp() <a class="header-anchor" href="#clamp" aria-label="Permalink to &quot;clamp()&quot;">​</a></h3><blockquote><p><strong>clamp</strong>(<code>lo</code>, <code>hi</code>, <code>ctx?</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/helix/src/core/frontend/nodes/fixed.ts#L111" target="_blank" rel="noreferrer">core/frontend/nodes/fixed.ts:111</a></p><p>Clamp the underlying score into <code>[lo, hi]</code> (<code>&lt; hi</code> then <code>&gt; lo</code>).</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="lo" tabindex="-1">lo <a class="header-anchor" href="#lo" aria-label="Permalink to &quot;lo&quot;">​</a></h5><p><a href="./Score.html"><code>Score</code></a></p><h5 id="hi" tabindex="-1">hi <a class="header-anchor" href="#hi" aria-label="Permalink to &quot;hi&quot;">​</a></h5><p><a href="./Score.html"><code>Score</code></a></p><h5 id="ctx-2" tabindex="-1">ctx? <a class="header-anchor" href="#ctx-2" aria-label="Permalink to &quot;ctx?&quot;">​</a></h5><p><a href="./FunctionContext.html"><code>FunctionContext</code></a></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="divide" tabindex="-1">divide() <a class="header-anchor" href="#divide" aria-label="Permalink to &quot;divide()&quot;">​</a></h3><blockquote><p><strong>divide</strong>(<code>divisor</code>, <code>ctx?</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/helix/src/core/frontend/nodes/fixed.ts#L89" target="_blank" rel="noreferrer">core/frontend/nodes/fixed.ts:89</a></p><p>Fixed-point <strong>divide</strong> by <code>divisor</code>, <strong>precision-preserving</strong>: pre-multiplies by the scale so the integer <code>/=</code> keeps <code>scale</code> fractional bits - <code>(a·scale)·scale / divisor</code> lands the quotient back at this scale instead of flooring to 0. This is the operation that defuses the classic “small numerator ÷ large divisor truncates to zero, the value silently vanishes” scoreboard bug. Emits <code>*= scale ; /= divisor</code>. <code>divisor</code> is any <code>Score</code>/<code>Fixed</code>. (Needs <code>scaleScore</code>.)</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="divisor" tabindex="-1">divisor <a class="header-anchor" href="#divisor" aria-label="Permalink to &quot;divisor&quot;">​</a></h5><p><a href="./Score.html"><code>Score</code></a> | <code>Fixed</code></p><h5 id="ctx-3" tabindex="-1">ctx? <a class="header-anchor" href="#ctx-3" aria-label="Permalink to &quot;ctx?&quot;">​</a></h5><p><a href="./FunctionContext.html"><code>FunctionContext</code></a></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="gain" tabindex="-1">gain() <a class="header-anchor" href="#gain" aria-label="Permalink to &quot;gain()&quot;">​</a></h3><blockquote><p><strong>gain</strong>(<code>k</code>, <code>ctx?</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/helix/src/core/frontend/nodes/fixed.ts#L95" target="_blank" rel="noreferrer">core/frontend/nodes/fixed.ts:95</a></p><p>Multiply by a <strong>unitless</strong> factor <code>k</code> (<code>*= k</code>); the scale is unchanged.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="k" tabindex="-1">k <a class="header-anchor" href="#k" aria-label="Permalink to &quot;k&quot;">​</a></h5><p><a href="./Score.html"><code>Score</code></a></p><h5 id="ctx-4" tabindex="-1">ctx? <a class="header-anchor" href="#ctx-4" aria-label="Permalink to &quot;ctx?&quot;">​</a></h5><p><a href="./FunctionContext.html"><code>FunctionContext</code></a></p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="mul" tabindex="-1">mul() <a class="header-anchor" href="#mul" aria-label="Permalink to &quot;mul()&quot;">​</a></h3><blockquote><p><strong>mul</strong>(<code>other</code>, <code>ctx?</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/helix/src/core/frontend/nodes/fixed.ts#L76" target="_blank" rel="noreferrer">core/frontend/nodes/fixed.ts:76</a></p><p>Fixed-point <strong>multiply</strong> by a same-scale <code>other</code>: <code>(a·scale)(b·scale)</code> would be <code>(ab)·scale²</code>, so we divide the scale back out to stay at this scale. Emits <code>*= other ; /= scale</code>. (Needs <code>scaleScore</code>.)</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="other-2" tabindex="-1">other <a class="header-anchor" href="#other-2" aria-label="Permalink to &quot;other&quot;">​</a></h5><p><code>Fixed</code></p><h5 id="ctx-5" tabindex="-1">ctx? <a class="header-anchor" href="#ctx-5" aria-label="Permalink to &quot;ctx?&quot;">​</a></h5><p><a href="./FunctionContext.html"><code>FunctionContext</code></a></p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="negate" tabindex="-1">negate() <a class="header-anchor" href="#negate" aria-label="Permalink to &quot;negate()&quot;">​</a></h3><blockquote><p><strong>negate</strong>(<code>negOne</code>, <code>ctx?</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/helix/src/core/frontend/nodes/fixed.ts#L66" target="_blank" rel="noreferrer">core/frontend/nodes/fixed.ts:66</a></p><p>Negate in place (<code>*= -1</code>). Scoreboards have no unary minus, so this multiplies by a caller-owned <code>-1</code> slot - clearer at the call site than spelling out the <code>times(negOne)</code> every time.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="negone" tabindex="-1">negOne <a class="header-anchor" href="#negone" aria-label="Permalink to &quot;negOne&quot;">​</a></h5><p><a href="./Score.html"><code>Score</code></a></p><h5 id="ctx-6" tabindex="-1">ctx? <a class="header-anchor" href="#ctx-6" aria-label="Permalink to &quot;ctx?&quot;">​</a></h5><p><a href="./FunctionContext.html"><code>FunctionContext</code></a></p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="reduce" tabindex="-1">reduce() <a class="header-anchor" href="#reduce" aria-label="Permalink to &quot;reduce()&quot;">​</a></h3><blockquote><p><strong>reduce</strong>(<code>k</code>, <code>ctx?</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/helix/src/core/frontend/nodes/fixed.ts#L105" target="_blank" rel="noreferrer">core/frontend/nodes/fixed.ts:105</a></p><p>Divide by a <strong>unitless</strong> integer factor <code>k</code> (<code>/= k</code>); the scale is unchanged. Unlike <a href="#divide">divide</a> this is a plain floor divide - use it for a gain/ratio constant (e.g. a stiffness divisor), not for dividing by another measured value.</p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="k-1" tabindex="-1">k <a class="header-anchor" href="#k-1" aria-label="Permalink to &quot;k&quot;">​</a></h5><p><a href="./Score.html"><code>Score</code></a></p><h5 id="ctx-7" tabindex="-1">ctx? <a class="header-anchor" href="#ctx-7" aria-label="Permalink to &quot;ctx?&quot;">​</a></h5><p><a href="./FunctionContext.html"><code>FunctionContext</code></a></p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="sub" tabindex="-1">sub() <a class="header-anchor" href="#sub" aria-label="Permalink to &quot;sub()&quot;">​</a></h3><blockquote><p><strong>sub</strong>(<code>other</code>, <code>ctx?</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/helix/src/core/frontend/nodes/fixed.ts#L56" target="_blank" rel="noreferrer">core/frontend/nodes/fixed.ts:56</a></p><p><code>this -= other</code> - same-scale subtraction is just integer <code>-=</code>.</p><h4 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="other-3" tabindex="-1">other <a class="header-anchor" href="#other-3" aria-label="Permalink to &quot;other&quot;">​</a></h5><p><a href="./Score.html"><code>Score</code></a> | <code>Fixed</code></p><h5 id="ctx-8" tabindex="-1">ctx? <a class="header-anchor" href="#ctx-8" aria-label="Permalink to &quot;ctx?&quot;">​</a></h5><p><a href="./FunctionContext.html"><code>FunctionContext</code></a></p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p>',141)])])}const p=a(c,[["render",d]]);export{b as __pageData,p as default};
